  aligned (V 2%nat) 16 -> L5.writable RSEGS M ((V 2%nat) - 80) 80 -> 7036928 <= (V 36%nat) <= 140737488355232 -> aligned (V 36%nat) 8 ->
  (2147446784 + 17592186048512 <= (V 36%nat) \/ (V 36%nat) + 96 <= 2147446784) -> L5KA.zeros_at M ((((V 36%nat) + 80) / 8) + 2147450880) 1 ->
